parameters.jsCode:
// Advanced detection: named-provider regexes + Shannon-entropy filtering on
// generic key=value assignments, deduped and masked, one item per finding.
const cfg = $('Set - Config').first().json;
const repoData = $('HTTP Request - Fetch Recent Repository Commits/Diffs').first().json;
const ciData = $('HTTP Request - Fetch CI/CD Pipeline Logs').first().json;

const repoContent = (repoData.files || repoData || []).map ? (repoData.files || []).map(f => ({ source: 'repo', location: f.filename || f.path || 'unknown', text: f.patch || f.content || '' })) : [];
const ciContent = (ciData.logs || []).map((l, i) => ({ source: 'ci', location: 'log-line-' + i, text: String(l) }));
const sources = [...repoContent, ...ciContent];

const PATTERNS = [
  { type: 'AWS Access Key', category: 'cloud', re: /AKIA[0-9A-Z]{16}/g },
  { type: 'AWS Secret Key', category: 'cloud', re: /[A-Za-z0-9\/+]{40}/g },
  { type: 'GitHub Personal Access Token', category: 'vcs', re: /gh[pousr]_[A-Za-z0-9]{36,255}/g },
  { type: 'GitLab Token', category: 'vcs', re: /glpat-[A-Za-z0-9\-_]{20}/g },
  { type: 'Slack Token', category: 'vcs', re: /xox[baprs]-[A-Za-z0-9-]{10,72}/g },
  { type: 'Stripe Live Key', category: 'payment', re: /sk_live_[0-9a-zA-Z]{24,}/g },
  { type: 'Stripe Restricted Key', category: 'payment', re: /rk_live_[0-9a-zA-Z]{24,}/g },
  { type: 'Google API Key', category: 'cloud', re: /AIza[0-9A-Za-z\-_]{35}/g },
  { type: 'Private Key Block', category: 'cloud', re: /-----BEGIN (RSA |EC |)PRIVATE KEY-----/g },
  { type: 'Generic Bearer YOUR_TOKEN_HERE', category: 'generic', re: /Bearer\s+[A-Za-z0-9\-\._~\+\/]{20,}/g }
];

function shannonEntropy(str) {
  const freq = {};
  for (const ch of str) freq[ch] = (freq[ch] || 0) + 1;
  let entropy = 0;
  const len = str.length;
  for (const ch in freq) {
    const p = freq[ch] / len;
    entropy -= p * Math.log2(p);
  }
  return entropy;
}

function maskValue(value) {
  if (value.length <= 8) return '***';
  return value.slice(0, 4) + '...' + value.slice(-4);
}

const findingsMap = new Map();

for (const src of sources) {
  for (const pattern of PATTERNS) {
    const matches = src.text.match(pattern.re) || [];
    for (const match of matches) {
      const entropy = shannonEntropy(match);
      if (pattern.category === 'generic' && entropy < 3.5) continue;
      const masked = maskValue(match);
      const key = pattern.type + ':' + masked;
      if (findingsMap.has(key)) continue;
      findingsMap.set(key, {
        secretType: pattern.type,
        category: pattern.category,
        source: src.source,
        location: src.location,
        maskedValue: masked,
        rawValueForVerificationOnly: match,
        entropyScore: Math.round(entropy * 100) / 100,
        confidencePercent: pattern.category === 'generic' ? Math.min(90, Math.round(entropy * 20)) : 95
      });
    }
  }

  // Generic .env-style KEY=value assignments not caught by a named pattern
  const kvMatches = src.text.match(/[A-Z0-9_]{4,}\s*[:=]\s*['"]?([A-Za-z0-9\/+_\-]{20,})['"]?/g) || [];
  for (const kv of kvMatches) {
    const valueMatch = kv.match(/['"]?([A-Za-z0-9\/+_\-]{20,})['"]?$/);
    if (!valueMatch) continue;
    const value = valueMatch[1];
    const entropy = shannonEntropy(value);
    if (entropy < 4.0) continue;
    const masked = maskValue(value);
    const key = 'Generic High-Entropy String:' + masked;
    if (findingsMap.has(key)) continue;
    findingsMap.set(key, {
      secretType: 'Generic High-Entropy String',
      category: 'generic',
      source: src.source,
      location: src.location,
      maskedValue: masked,
      rawValueForVerificationOnly: value,
      entropyScore: Math.round(entropy * 100) / 100,
      confidencePercent: Math.min(85, Math.round(entropy * 18))
    });
  }
}

const findings = [...findingsMap.values()];

if (findings.length === 0) {
  return [{ json: { ...cfg, noFindings: true } }];
}

return findings.map(f => ({ json: { ...cfg, ...f, noFindings: false } }));

