=🚨 URGENT: Secret still ACTIVE after remediation was marked confirmed.
Type: {{ $json.secretType }}
Masked value: {{ $json.maskedValue }}
Source: {{ $json.source }} at {{ $json.location }}
This needs immediate re-investigation — the reported rotation did not take effect.

parameters.jsCode:
// Advanced risk scoring: secret type + exposure surface + live/revoked status,
// plus a per-type remediation checklist and a WhatsApp-ready summary message.
const item = $input.first().json;

let verified = null;
if (item.verified === 'null' || item.verified === null) {
  verified = null;
} else if (item.error || (item.statusCode && item.statusCode >= 400)) {
  verified = false;
} else if (item.verificationApiUrl) {
  verified = true;
}

const CATEGORY_BASE_SCORE = { cloud: 40, vcs: 30, payment: 45, generic: 15 };
const SOURCE_MULTIPLIER = { repo: 1.5, ci: 1.0 };

let score = (CATEGORY_BASE_SCORE[item.category] || 10) * (SOURCE_MULTIPLIER[item.source] || 1);
score += (item.confidencePercent || 0) * 0.3;
if (verified === true) score += 30;
if (verified === false) score -= 15;
score = Math.max(0, Math.min(100, Math.round(score)));

let severity = 'low';
if (score >= 75) severity = 'critical';
else if (score >= 55) severity = 'high';
else if (score >= 30) severity = 'medium';

const CHECKLISTS = {
  'AWS Access Key': ['Deactivate/delete the key pair in IAM immediately.', 'Review CloudTrail for unauthorized activity since exposure.', 'Rotate any dependent services using this key.'],
  'AWS Secret Key': ['Deactivate/delete the associated access key in IAM immediately.', 'Review CloudTrail for unauthorized activity.', 'Rotate dependent services.'],
  'GitHub Personal Access Token': ['Revoke the token in GitHub Settings > Developer settings.', 'Check the audit log for unexpected repository access.', 'Reissue a scoped, short-lived token instead.'],
  'GitLab Token': ['Revoke the token in GitLab user settings.', 'Review project access logs.'],
  'Slack Token': ['Revoke the token/app installation in Slack admin.', 'Rotate and re-scope minimally.'],
  'Stripe Live Key': ['Roll the key immediately in the Stripe dashboard.', 'Review recent charges/payouts for anomalies.', 'Notify finance/security of potential exposure.'],
  'Stripe Restricted Key': ['Roll the key immediately in the Stripe dashboard.', 'Review scoped resource access logs.'],
  'Google API Key': ['Restrict or regenerate the key in Google Cloud Console.', 'Add application/IP restrictions going forward.'],
  'Private Key Block': ['Revoke/rotate the corresponding certificate or SSH key immediately.', 'Audit systems that trusted this key.'],
  'Generic Bearer YOUR_TOKEN_HERE': ['Identify the issuing service and revoke the token there.', 'Search for other usages of the same token.'],
  'Generic High-Entropy String': ['Manually confirm whether this is a real secret.', 'If confirmed, identify the issuing service and rotate it.']
};
const checklist = CHECKLISTS[item.secretType] || ['Manually investigate and rotate if confirmed sensitive.'];

const alertRequired = severity === 'critical' || severity === 'high' || severity === 'medium';

const whatsappMessage = 'Secret exposure detected: ' + item.secretType + ' (' + severity.toUpperCase() + ', risk score ' + score + '/100)\nSource: ' + item.source + ' at ' + item.location + '\nMasked value: ' + item.maskedValue + '\nStill valid: ' + (verified === null ? 'unknown - manual check needed' : (verified ? 'YES - still active' : 'No - appears already revoked')) + '\nNext steps: ' + checklist.join(' | ');

return [{
  json: {
    ...item,
    verified,
    riskScore: score,
    severity,
    checklist,
    alertRequired,
    whatsappMessage
  }
}];
